import{_ as e,o as a,c as n,a2 as o}from"./chunks/framework.eFe5Lsvn.js";const i="/Mayhem/img/constraints.jpg",u=JSON.parse('{"title":"Constraints","description":"","frontmatter":{},"headers":[],"relativePath":"app/constraints.md","filePath":"app/constraints.md"}'),r={name:"app/constraints.md"};function s(h,t,p,l,d,c){return a(),n("div",null,[...t[0]||(t[0]=[o('<h1 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h1><p>Open the <strong>Constraint</strong> menu in the toolbar and pick a type, then <strong>click the first waypoint and the last waypoint</strong> it applies to. Click one waypoint and press <kbd>↵</kbd> to apply it to just that waypoint.</p><p><img src="'+i+'" alt="The Constraint menu"></p><table tabindex="0"><thead><tr><th>Constraint</th><th>Effect</th></tr></thead><tbody><tr><td>Max velocity / acceleration / angular velocity</td><td>Limits between the two waypoints.</td></tr><tr><td>Straight line</td><td>The robot drives on the straight line between the two waypoints (± tolerance).</td></tr><tr><td>Point at</td><td>The robot faces a target. Drag the crosshair; it starts at the hub.</td></tr><tr><td>Keep in / Keep out region</td><td>Draw a polygon instead of picking waypoints.</td></tr><tr><td>Rough terrain</td><td>Draw a polygon over a bump. See <a href="#rough-terrain">below</a>.</td></tr><tr><td>Intake extended</td><td>The intake is out between the two waypoints, or in a zone. See <a href="#intake-extended">below</a>.</td></tr></tbody></table><p>Selecting a constraint highlights the part of the path it covers. In its panel you can change the limit, move it to other waypoints, or make a velocity limit apply <strong>in a zone</strong> (a drawn region) instead.</p><h2 id="intake-extended" tabindex="-1">Intake extended <a class="header-anchor" href="#intake-extended" aria-label="Permalink to &quot;Intake extended&quot;">​</a></h2><p>The intake (set in <strong>Settings → Robot</strong>) is out between the two waypoints, or in a zone. The solver keeps the intake clear of obstacles and walls there as well as the bumpers. The field shows the intake on those waypoints and highlights that stretch of the path in amber.</p><p>On the robot, bind your deploy command to <code>AutoTrajectory.intakeExtended()</code>:</p><div class="language-java vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">java</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">traj.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">intakeExtended</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">whileTrue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(intake.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">deploy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">());</span></span></code></pre></div><h2 id="rough-terrain" tabindex="-1">Rough terrain <a class="header-anchor" href="#rough-terrain" aria-label="Permalink to &quot;Rough terrain&quot;">​</a></h2><p>Rough terrain can come from two places, and both end up in the exported path:</p><ul><li><strong>The field (recommended for bumps).</strong> In <a href="/Mayhem/app/field">Field mode</a>, select an obstacle and turn on <strong>Rough terrain on every path</strong>. Every path that crosses it gets a span automatically, so it persists across all your paths. The REBUILT preset already marks its four bumps this way. Editing it marks existing paths out of date; regenerate them to refresh their spans.</li><li><strong>A single path.</strong> Draw a rough-terrain polygon with the constraint tool for terrain that only matters to one path.</li></ul><p>The solver keeps its planned speed; the exported path marks the covered samples for the robot library. Where a field zone and a path zone overlap, the spans merge and the lower speed fraction and correction strength win. A span covers the time the robot <em>center</em> is inside the shape (plus 5 cm), so draw it over the part of the bump the robot center crosses.</p><p>On the robot, MayhemLib pauses collision detection and replanning in the zone, slows the path clock to follow the robot&#39;s progress, and softens feedback. After leaving the zone, it temporarily raises the vision-trust signal. Event markers continue to fire as trajectory time advances. See <a href="/Mayhem/lib/recovery#rough-terrain-zones">Bump recovery</a>.</p><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Prefer a <strong>position tolerance</strong> on a waypoint over a tight constraint when you can. It gives the solver room to find a path.</li><li>A <strong>Point at</strong> constraint conflicts with a fixed heading at a waypoint inside its range. Loosen the heading tolerance or make the heading free.</li></ul>',16)])])}const m=e(r,[["render",s]]);export{u as __pageData,m as default};
